package com.cirro.android;

import android.app.Activity;
import android.content.Intent;
import android.net.Uri;
import android.database.Cursor;
import android.provider.OpenableColumns;
import androidx.activity.result.ActivityResult;
import com.getcapacitor.*;
import com.getcapacitor.annotation.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;
import org.json.JSONObject;

@CapacitorPlugin(name="FileTransfers")
public class FileTransfersPlugin extends Plugin {
 private static final Set<String> cancelled=ConcurrentHashMap.newKeySet();
 private static final ConcurrentHashMap<String,HttpURLConnection> connections=new ConcurrentHashMap<>();
 private final ExecutorService worker=Executors.newSingleThreadExecutor();
 @Override public void load(){File[] files=getContext().getCacheDir().listFiles();if(files!=null)for(File file:files)if(file.getName().startsWith("cirro-transfer-")&&file.getName().endsWith(".part")&&System.currentTimeMillis()-file.lastModified()>86400000L)file.delete();}
 private static final String FIELDS="id,name,mimeType,parents,size,md5Checksum,version,modifiedTime,webViewLink,driveId,capabilities(canTrash,canCopy,canDownload,canAddChildren),appProperties";
 static void cancelAll(){for(String id:connections.keySet()){cancelled.add(id);connections.get(id).disconnect();}}
 @PluginMethod public void cancel(PluginCall call){String id=call.getString("id","");cancelled.add(id);HttpURLConnection connection=connections.get(id);if(connection!=null)connection.disconnect();call.resolve();}
 private void check(String id)throws IOException{if(cancelled.contains(id))throw new IOException("Transfer cancelled. Completed destination copies were kept.");}
 @PluginMethod public void pickFiles(PluginCall call){Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(call,intent,"picked");}
 @ActivityCallback private void picked(PluginCall call,ActivityResult result){if(call==null)return;JSArray files=new JSArray();if(result.getResultCode()!=Activity.RESULT_OK||result.getData()==null){call.resolve(new JSObject().put("files",files));return;}try{Intent data=result.getData();List<Uri> uris=new ArrayList<>();if(data.getClipData()!=null){for(int i=0;i<data.getClipData().getItemCount();i++)uris.add(data.getClipData().getItemAt(i).getUri());}else if(data.getData()!=null)uris.add(data.getData());for(Uri uri:uris){if(!"content".equals(uri.getScheme()))throw new IOException();try{getContext().getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException ignored){}String name="Upload",mime=getContext().getContentResolver().getType(uri);long size=-1;try(Cursor cursor=getContext().getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME,OpenableColumns.SIZE},null,null,null)){if(cursor!=null&&cursor.moveToFirst()){name=cursor.getString(0);if(!cursor.isNull(1))size=cursor.getLong(1);}}files.put(new JSObject().put("uri",uri.toString()).put("name",name).put("mime",mime==null?"application/octet-stream":mime).put("size",size));}call.resolve(new JSObject().put("files",files));}catch(Exception error){call.reject("Could not read the selected files. Choose files from device storage.");}}
 private HttpURLConnection connection(String id,String address,String token,String method)throws Exception{check(id);URL url=new URL(address);if(!"https".equals(url.getProtocol())||!("www.googleapis.com".equals(url.getHost())||"content.googleapis.com".equals(url.getHost())))throw new IOException("Invalid Google upload endpoint.");HttpURLConnection connection=(HttpURLConnection)url.openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(20000);connection.setReadTimeout(60000);connection.setRequestMethod(method);connection.setRequestProperty("Authorization","Bearer "+token);connections.put(id,connection);return connection;}
 private String read(HttpURLConnection connection)throws Exception{InputStream stream=connection.getResponseCode()<400?connection.getInputStream():connection.getErrorStream();try(InputStream input=stream;ByteArrayOutputStream out=new ByteArrayOutputStream()){if(input==null)return "";byte[] buffer=new byte[4096];int count;while((count=input.read(buffer))!=-1){if(out.size()+count>2*1024*1024)throw new IOException("Google response is too large.");out.write(buffer,0,count);}return out.toString("UTF-8");}}
 private void success(HttpURLConnection connection)throws Exception{int status=connection.getResponseCode();if(status<200||status>=300){String body=read(connection);if(status==401||body.contains("ACCESS_TOKEN_SCOPE_INSUFFICIENT")||body.contains("insufficientPermissions"))throw new SecurityException("Drive access expired. Reconnect the account in Sync, then retry.");throw new IOException("Google Drive transfer failed ("+status+"). "+(body.length()<1000?body:"Check your permissions and available storage."));}}
 private void progress(String id,long bytes,long total,String phase){notifyListeners("progress",new JSObject().put("id",id).put("bytes",bytes).put("total",total).put("phase",phase));}
 private File stage(PluginCall call,String id,boolean remote)throws Exception{File file=File.createTempFile("cirro-transfer-",".part",getContext().getCacheDir());HttpURLConnection source=null;try{InputStream input;if(remote){String sourceId=call.getString("sourceId","");if(!sourceId.matches("[a-zA-Z0-9_-]+"))throw new IOException("Invalid source file.");source=connection(id,"https://www.googleapis.com/drive/v3/files/"+sourceId+"?alt=media&supportsAllDrives=true",call.getString("sourceToken"),"GET");String resource=call.getString("resourceKey");if(resource!=null&&resource.matches("[a-zA-Z0-9_-]+"))source.setRequestProperty("X-Goog-Drive-Resource-Keys",sourceId+"/"+resource);success(source);input=source.getInputStream();}else{Uri uri=Uri.parse(call.getString("uri",""));if(!"content".equals(uri.getScheme()))throw new IOException("Choose the upload file again.");input=getContext().getContentResolver().openInputStream(uri);}long total=call.getLong("size",-1L),written=0,last=0;try(InputStream in=input;OutputStream out=new FileOutputStream(file)){if(in==null)throw new IOException("The selected file is unavailable.");byte[] buffer=new byte[65536];int count;while((count=in.read(buffer))!=-1){check(id);out.write(buffer,0,count);written+=count;if(System.currentTimeMillis()-last>200){progress(id,written,total,remote?"Downloading":"Preparing");last=System.currentTimeMillis();}}}if(total>=0&&written!=total)throw new IOException("Source size changed or download was interrupted. Source retained.");return file;}catch(Exception error){file.delete();throw error;}finally{if(source!=null)source.disconnect();connections.remove(id);}}
 private JSONObject upload(PluginCall call,String id,File file)throws Exception{
  String token=call.getString("token"),mime=call.getString("mime","application/octet-stream"),parent=call.getString("parent","");if(!parent.matches("[a-zA-Z0-9_-]+"))throw new IOException("Invalid destination folder.");String name=call.getString("name","Upload");JSONObject metadata=new JSONObject().put("name",name).put("mimeType",mime).put("parents",new org.json.JSONArray().put(parent)).put("appProperties",new JSONObject().put("cirroTransfer",call.getString("marker")));
  HttpURLConnection session=connection(id,"https://www.googleapis.com/upload/drive/v3/files?uploadType=resumable&supportsAllDrives=true&fields="+URLEncoder.encode(FIELDS,"UTF-8"),token,"POST");String location;try{byte[] data=metadata.toString().getBytes(StandardCharsets.UTF_8);session.setDoOutput(true);session.setRequestProperty("Content-Type","application/json; charset=UTF-8");session.setRequestProperty("X-Upload-Content-Type",mime);session.setRequestProperty("X-Upload-Content-Length",String.valueOf(file.length()));session.setFixedLengthStreamingMode(data.length);try(OutputStream out=session.getOutputStream()){out.write(data);}success(session);location=session.getHeaderField("Location");if(location==null)throw new IOException("Google did not return an upload session.");}finally{session.disconnect();}
  long total=file.length(),offset=0;try(RandomAccessFile input=new RandomAccessFile(file,"r")){while(offset<total||total==0){check(id);int length=(int)Math.min(1024*1024,total-offset);byte[] buffer=new byte[length];input.seek(offset);input.readFully(buffer);boolean uploaded=false;Exception failure=null;for(int attempt=0;attempt<3&&!uploaded;attempt++){HttpURLConnection part=connection(id,location,token,"PUT");try{part.setDoOutput(true);part.setRequestProperty("Content-Type",mime);part.setRequestProperty("Content-Range",total==0?"bytes */0":"bytes "+offset+"-"+(offset+length-1)+"/"+total);part.setFixedLengthStreamingMode(length);try(OutputStream out=part.getOutputStream()){out.write(buffer);}int status=part.getResponseCode();if(status==200||status==201){JSONObject result=new JSONObject(read(part));if(!String.valueOf(total).equals(result.optString("size")))throw new IOException("Uploaded size could not be verified. Source retained.");progress(id,total,total,"Uploaded");return result;}if(status==308){String range=part.getHeaderField("Range");long next=range==null?0:Long.parseLong(range.substring(range.lastIndexOf('-')+1))+1;if(next<offset||next>offset+length)throw new IOException("Invalid upload acknowledgement.");offset=next;uploaded=true;progress(id,offset,total,"Uploading");}else{success(part);throw new IOException("Unexpected upload response.");}}catch(SecurityException error){throw error;}catch(Exception error){failure=error;if(attempt==2)throw error;check(id);Thread.sleep(500L*(attempt+1));HttpURLConnection probe=connection(id,location,token,"PUT");try{probe.setDoOutput(true);probe.setFixedLengthStreamingMode(0);probe.setRequestProperty("Content-Range","bytes */"+total);probe.getOutputStream().close();int status=probe.getResponseCode();if(status==200||status==201)return new JSONObject(read(probe));if(status==308){String range=probe.getHeaderField("Range");long acknowledged=range==null?0:Long.parseLong(range.substring(range.lastIndexOf('-')+1))+1;if(acknowledged!=offset){offset=acknowledged;uploaded=true;}}else success(probe);}finally{probe.disconnect();}}finally{part.disconnect();}}if(!uploaded&&failure!=null)throw failure;if(total==0)break;}}
  throw new IOException("Upload did not complete. Retry from Transfers.");
 }
 private void perform(PluginCall call,boolean remote){worker.execute(()->{String id=call.getString("id","");File staged=null;try{check(id);staged=stage(call,id,remote);JSONObject result=upload(call,id,staged);if(result.optLong("size",-1)!=staged.length())throw new IOException("Uploaded size did not match. Source retained.");MessageDigest digest=MessageDigest.getInstance("MD5");try(InputStream input=new FileInputStream(staged)){byte[] data=new byte[65536];int count;while((count=input.read(data))!=-1){check(id);digest.update(data,0,count);}}StringBuilder checksum=new StringBuilder();for(byte value:digest.digest())checksum.append(String.format("%02x",value));if(!checksum.toString().equals(result.optString("md5Checksum")))throw new IOException("Uploaded checksum did not match. Source retained.");call.resolve(JSObject.fromJSONObject(result));}catch(SecurityException error){call.reject(error.getMessage(),"DRIVE_CONSENT_REQUIRED");}catch(Exception error){call.reject(error.getMessage()==null?"Transfer failed. Check your connection and storage.":error.getMessage());}finally{if(staged!=null)staged.delete();connections.remove(id);cancelled.remove(id);}});}
 @PluginMethod public void upload(PluginCall call){perform(call,false);}
 @PluginMethod public void copyBinary(PluginCall call){perform(call,true);}
}
